77	  workspace.importJSON(readSnapshotFile(base), { mode: 'replace' });
78	  const snapshot = workspace.importJSON(readSnapshotFile(incoming), { mode, dryRun });
79	
80	  const rendered = `${JSON.stringify(snapshot)}\n`;
81	  if (!dryRun) atomicWrite(output, rendered);
