86	  const positionals = [];
87	  let dryRun = false;
88	  for (const arg of args) {
89	    if (arg === '--dry-run') {
90	      dryRun = true;
91	    } else if (arg.startsWith('--')) {
92	      throw new SnapshotError('INVALID_OPTIONS', `unknown option: ${arg}`);
