  assert.equal(fs.readFileSync(path.join(cwd, 'out.json'), 'utf8'), replaced.stdout);

  const base = workspaceWith([{ id: 'base-doc', title: 'Base', body: 'see [[welcome]]', tags: ['b'] }]);
