  const merged = runCli(['import-md', 'base.json', 'pkg', 'merged.json', 'merge'], cwd);
  assert.equal(merged.status, 0);
  assert.deepEqual(
    JSON.parse(merged.stdout.trim()).documents.map((d) => d.id),
    ['a.b', 'architecture', 'base-doc', 'welcome'],
  );
});

