276	// Exports a version-1 JSON snapshot file into a Markdown package directory.
277	// The package is materialized in a sibling staging directory and swapped into
278	// place with a single rename; fixed staging/backup names let a retry after a
279	// killed export finish a complete package with no stale files left behind.
280	export function exportMarkdown(snapshotFile, outputDirectory) {
281	  const output = path.resolve(outputDirectory);
282	  const parent = path.dirname(output);
283	  let parentStats;
284	  try {
285	    // Follow symlinked ancestors: only the target leaf itself being a symlink
286	    // is rejected below.
287	    parentStats = fs.statSync(parent);
288	  } catch (error) {
289	    throw ioError(`cannot access output parent ${parent}: ${error.message}`);
290	  }
291	  if (!parentStats.isDirectory()) throw ioError(`output parent is not a directory: ${parent}`);
292	
293	  let outputStats;
294	  try {
295	    outputStats = fs.lstatSync(output);
296	  } catch (error) {
297	    if (error.code !== 'ENOENT') throw ioError(`cannot access output directory ${outputDirectory}: ${error.message}`);
298	  }
299	  if (outputStats?.isSymbolicLink()) {
300	    throw new SnapshotError('INVALID_OPTIONS', 'output directory must not be a symlink');
301	  }
302	
303	  // Fixed sibling names used to replace the target wholesale and to finish a
304	  // killed retry; both are removed before the package is built.
305	  const stage = `${output}.export.tmp`;
306	  const backup = `${output}.old.tmp`;
307	
308	  // Path-option checks precede reading so an invalid layout is reported even
309	  // when the source itself would be unreadable, and before any location the
310	  // export deletes or replaces is touched. The source snapshot is user input:
311	  // it must never be the target directory or the staging/backup directory,
312	  // nor live inside any of them, or the cleanup below could delete a snapshot
313	  // that was already read successfully. Real locations make aliased paths
314	  // (including symlinked parents of a not-yet-created target) compare equal.
315	  const sourceReal = realLocation(snapshotFile);
316	  const scratchLocations = [
317	    { real: realLocation(output), message: 'output directory must not contain the source snapshot' },
318	    { real: realLocation(stage), message: 'source snapshot must not be in the export staging directory' },
319	    { real: realLocation(backup), message: 'source snapshot must not be in the export backup directory' },
320	  ];
