328	
329	  // All content validation happens before anything on disk changes.
330	  const workspace = new Workspace();
331	  workspace.importJSON(snapshotText, { mode: 'replace' });
332	  const snapshot = workspace.exportJSON();
333	  const { files, manifestText } = buildPackage(snapshot);
334	
335	  // Clear leftovers from a previously killed attempt first.
336	  removeQuiet(stage);
337	  removeQuiet(backup);
338	  let stageReady = false;
339	  try {
340	    fs.mkdirSync(stage);
341	    for (const [name, bytes] of files) fs.writeFileSync(path.join(stage, name), bytes);
342	    stageReady = true;
343	
344	    const hadTarget = outputStats !== undefined;
345	    if (hadTarget) fs.renameSync(output, backup);
