360	    if (stageReady) removeQuiet(stage);
361	    if (error instanceof SnapshotError) throw error;
362	    throw ioError(`cannot write package directory ${outputDirectory}: ${error.message}`);
363	  }
364	
365	  return { manifest: JSON.parse(manifestText), manifestText };
366	}
