const cwd = fs.mkdtempSync(path.join(os.tmpdir(), 'verify-export-'));
const ws = new Workspace();
ws.add({ id: 'a', title: 'A', body: 'hello [[b]]', tags: [] });
const snapText = `${JSON.stringify(ws.exportJSON())}\n`;

function runCli(args) {
  try {
    const stdout = execFileSync(process.execPath, [CLI, ...args], { cwd, encoding: 'utf8' });
    return { status: 0, stdout, stderr: '' };
  } catch (e) {
    return { status: e.status ?? 1, stdout: e.stdout?.toString() ?? '', stderr: e.stderr?.toString() ?? '' };
  }
