let passed = 0;
function expectReject(label, setup, snapshotRel, outputRel, checkUntouched) {
  const dir = path.join(cwd, `case-${label}`);
  fs.mkdirSync(dir, { recursive: true });
  const { snapRel, others } = setup(dir);
  const before = new Map();
  for (const f of [...others, snapRel]) before.set(f, fs.readFileSync(path.join(dir, f)));
  const r = runCli(['export-md', snapRel, outputRel], dir);
  assert.equal(r.status, 1, `${label}: status`);
  assert.equal(r.stdout, '', `${label}: stdout empty`);
  assert.equal(JSON.parse(r.stderr.trim()).code, 'INVALID_OPTIONS', `${label}: code`);
  // source and pre-existing content untouched
  for (const [f, bytes] of before) {
    assert.ok(fs.existsSync(path.join(dir, f)), `${label}: ${f} still exists`);
    assert.deepEqual(fs.readFileSync(path.join(dir, f)), bytes, `${label}: ${f} unchanged`);
  }
  // no markdown package dir created at output
  checkUntouched(dir);
  passed += 1;
}

