  assert.equal(r.status, 0, 'name-sharing sibling is allowed');
  assert.ok(fs.existsSync(path.join(d, 'pkg', 'manifest.json')));
  assert.ok(fs.existsSync(path.join(d, 'pkg-backups', 'snap.json')));
