import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { Workspace } from '/opt/gsb-production/workspaces/sl-chen/prod-04/B/task010/src/workspace.js';
import { exportMarkdown } from '/opt/gsb-production/workspaces/sl-chen/prod-04/B/task010/src/markdown-pkg.js';

const CLI = '/opt/gsb-production/workspaces/sl-chen/prod-04/B/task010/src/cli.js';
const root = fs.mkdtempSync(path.join(os.tmpdir(), 'verify-export-'));
const ws = new Workspace();
ws.add({ id: 'a', title: 'A', body: 'hello [[b]]', tags: [] });
const snapText = `${JSON.stringify(ws.exportJSON())}\n`;

function runCli(args, cwd) {
  try {
    const stdout = execFileSync(process.execPath, [CLI, ...args], { cwd, encoding: 'utf8' });
    return { status: 0, stdout, stderr: '' };
  } catch (e) {
    return { status: e.status ?? 1, stdout: e.stdout?.toString() ?? '', stderr: e.stderr?.toString() ?? '' };
  }
}

let n = 0;
function caseDir() {
  const d = path.join(root, `c${n++}`);
  fs.mkdirSync(d, { recursive: true });
  return d;
}

// Asserts the CLI refuses with INVALID_OPTIONS and the named files survive unchanged.
function assertRefused(cwd, args, preservedFiles, absentPaths) {
  const before = new Map(preservedFiles.map((f) => [f, fs.readFileSync(path.join(cwd, f))]));
  const r = runCli(args, cwd);
  assert.equal(r.status, 1, 'exit 1');
  assert.equal(r.stdout, '', 'stdout empty');
  const lines = r.stderr.split('\n');
  assert.equal(lines.length, 2, 'one stderr JSON line');
  assert.equal(JSON.parse(lines[0]).code, 'INVALID_OPTIONS', 'code INVALID_OPTIONS');
  for (const [f, bytes] of before) assert.deepEqual(fs.readFileSync(path.join(cwd, f)), bytes, `${f} unchanged`);
  for (const p of absentPaths) assert.ok(!fs.existsSync(path.join(cwd, p)), `${p} not created`);
}

// Asserts the API refuses with INVALID_OPTIONS and source survives.
function assertApiRefused(snap, out, cwd, preserved) {
  const before = new Map(preserved.map((f) => [f, fs.readFileSync(path.join(cwd, f))]));
  assert.throws(() => exportMarkdown(snap, out), (e) => e.code === 'INVALID_OPTIONS');
  for (const [f, bytes] of before) assert.deepEqual(fs.readFileSync(path.join(cwd, f)), bytes, `${f} survives`);
}

// --- Case 1: source inside EXISTING output directory ------------------------
{
  const d = caseDir();
  fs.mkdirSync(path.join(d, 'pkg'));
  fs.writeFileSync(path.join(d, 'pkg', 'keep.txt'), 'keep');
  fs.writeFileSync(path.join(d, 'pkg', 'snap.json'), snapText);
  assertRefused(d, ['export-md', 'pkg/snap.json', 'pkg'], ['pkg/snap.json', 'pkg/keep.txt'], []);
  assert.ok(fs.existsSync(path.join(d, 'pkg')), 'target dir still present');
}

// --- Case 2 (THE BUG): source is the staging dir itself ---------------------
{
  const d = caseDir();
  fs.mkdirSync(path.join(d, 'pkg.export.tmp'));
  fs.writeFileSync(path.join(d, 'pkg.export.tmp', 'snap.json'), snapText);
  assertRefused(d, ['export-md', 'pkg.export.tmp/snap.json', 'pkg'], ['pkg.export.tmp/snap.json'], ['pkg']);
  assert.ok(fs.existsSync(path.join(d, 'pkg.export.tmp')), 'stage dir survives');
}

// --- Case 3 (THE BUG): source is the backup dir itself ----------------------
{
  const d = caseDir();
  fs.mkdirSync(path.join(d, 'pkg.old.tmp'));
  fs.writeFileSync(path.join(d, 'pkg.old.tmp', 's.json'), snapText);
  assertRefused(d, ['export-md', 'pkg.old.tmp/s.json', 'pkg'], ['pkg.old.tmp/s.json'], ['pkg']);
  assert.ok(fs.existsSync(path.join(d, 'pkg.old.tmp')), 'backup dir survives');
}

// --- Case 4: output does NOT exist yet, source at stage location ------------
{
  const d = caseDir();
  fs.mkdirSync(path.join(d, 'pkg.export.tmp'));
  fs.writeFileSync(path.join(d, 'pkg.export.tmp', 'snap.json'), snapText);
  assertApiRefused(path.join(d, 'pkg.export.tmp', 'snap.json'), path.join(d, 'pkg'), d, ['pkg.export.tmp/snap.json']);
  assert.ok(!fs.existsSync(path.join(d, 'pkg')), 'output never created');
}

// --- Case 5: source path literally equal to output path --------------------
{
  const d = caseDir();
  fs.writeFileSync(path.join(d, 'pkg'), snapText); // same path used as source and output
  assertApiRefused(path.join(d, 'pkg'), path.join(d, 'pkg'), d, ['pkg']);
}

// --- Case 6: symlinked parent alias -> real location still rejected ---------
{
  const d = caseDir();
  fs.mkdirSync(path.join(d, 'data'));
  fs.writeFileSync(path.join(d, 'data', 'snap.json'), snapText);
  fs.symlinkSync('data', path.join(d, 'link'));
  // refer to source via symlink alias, output via real dir; both resolve into data
  assertApiRefused(path.join(d, 'link', 'snap.json'), path.join(d, 'data'), d, ['data/snap.json']);
}

// --- Case 7: symlinked parent of a NOT-YET-EXISTING output still caught -----
{
  const d = caseDir();
  fs.mkdirSync(path.join(d, 'deep', 'real'), { recursive: true });
  fs.symlinkSync('real', path.join(d, 'deep', 'r'));
  fs.writeFileSync(path.join(d, 'deep', 'real', 's.json'), snapText);
  // output 'deep/r/pkg' resolves to deep/real/pkg; source deep/real/s.json
  assertApiRefused(path.join(d, 'deep', 'real', 's.json'), path.join(d, 'deep', 'r', 'pkg'), d, ['deep/real/s.json']);
}

// --- Case 8: SAFE source outside despite tmp-sounding name / shared prefix --
{
  const d = caseDir();
  fs.writeFileSync(path.join(d, 'my-snapshot.export.tmp.json'), snapText);
  const r = runCli(['export-md', 'my-snapshot.export.tmp.json', 'pkg'], d);
  assert.equal(r.status, 0, 'safe tmp-named source exports');
  assert.ok(fs.existsSync(path.join(d, 'pkg', 'manifest.json')));
  assert.ok(fs.existsSync(path.join(d, 'my-snapshot.export.tmp.json')), 'source intact');
}

// --- Case 9: SAFE source in sibling that merely shares the name segment -----
{
  const d = caseDir();
  fs.mkdirSync(path.join(d, 'pkg-backups'));
  fs.writeFileSync(path.join(d, 'pkg-backups', 'snap.json'), snapText);
  const r = runCli(['export-md', 'pkg-backups/snap.json', 'pkg'], d);
  assert.equal(r.status, 0, 'name-sharing sibling is allowed');
  assert.ok(fs.existsSync(path.join(d, 'pkg', 'manifest.json')));
  assert.ok(fs.existsSync(path.join(d, 'pkg-backups', 'snap.json')));
}

// --- Case 10: normal successful export still byte-identical / checksum -----
{
  const d = caseDir();
  fs.writeFileSync(path.join(d, 'snap.json'), snapText);
  const first = runCli(['export-md', 'snap.json', 'pkg'], d);
  assert.equal(first.status, 0);
  const m1 = fs.readFileSync(path.join(d, 'pkg', 'manifest.json'));
  const a1 = fs.readFileSync(path.join(d, 'pkg', 'a.md'));
  const second = runCli(['export-md', 'snap.json', 'pkg'], d);
  assert.equal(second.status, 0);
  assert.deepEqual(fs.readFileSync(path.join(d, 'pkg', 'manifest.json')), m1, 'repeat byte-identical');
  assert.deepEqual(fs.readFileSync(path.join(d, 'pkg', 'a.md')), a1);
  assert.equal(a1.toString('utf8'), 'hello [[b]]', 'raw body bytes');
  assert.equal(JSON.parse(first.stdout.trim()).checksum, JSON.parse(snapText).checksum, 'bound checksum');
}

// --- Case 11: unrelated INVALID_SNAPSHOT still reports its own category -----
{
  const d = caseDir();
  fs.writeFileSync(path.join(d, 'bad.json'), '{not json');
  const r = runCli(['export-md', 'bad.json', 'pkg'], d);
  assert.equal(r.status, 1);
  assert.equal(JSON.parse(r.stderr.trim()).code, 'INVALID_SNAPSHOT', 'validation error not path conflict');
}

console.log(`ALL ${n} scenario groups passed`);

