  assert.deepEqual(fs.readFileSync(path.join(d, 'pkg', 'manifest.json')), m1, 'repeat byte-identical');
  assert.deepEqual(fs.readFileSync(path.join(d, 'pkg', 'a.md')), a1);
  assert.equal(a1.toString('utf8'), 'hello [[b]]', 'raw body bytes');
  assert.equal(JSON.parse(first.stdout.trim()).checksum, JSON.parse(snapText).checksum, 'bound checksum');
}

// --- Case 11: unrelated INVALID_SNAPSHOT still reports its own category -----
{
  const d = caseDir();
  fs.writeFileSync(path.join(d, 'bad.json'), '{not json');
  const r = runCli(['export-md', 'bad.json', 'pkg'], d);
  assert.equal(r.status, 1);
  assert.equal(JSON.parse(r.stderr.trim()).code, 'INVALID_SNAPSHOT', 'validation error not path conflict');
}

