test('export refuses a source snapshot in the output, staging, or backup location without deleting it', () => {
  const cwd = tempDir();
  const snapshotPath = path.join(cwd, 'snap.json');
  writeSnapshot(snapshotPath, workspaceWith(sampleDocuments));
  const target = path.join(cwd, 'pkg');

  const layouts = [
    // Source inside an existing target directory.
    () => {
      fs.mkdirSync(target);
      fs.writeFileSync(path.join(target, 'keep.txt'), 'keep');
      fs.copyFileSync(snapshotPath, path.join(target, 'snap.json'));
      return { source: path.join(target, 'snap.json'), output: target, watch: [path.join(target, 'snap.json'), path.join(target, 'keep.txt')] };
    },
    // Source inside the fixed staging directory (removed before building).
    () => {
      fs.mkdirSync(`${target}.export.tmp`);
      fs.copyFileSync(snapshotPath, `${target}.export.tmp/snap.json`);
      return { source: `${target}.export.tmp/snap.json`, output: target, watch: [`${target}.export.tmp/snap.json`] };
    },
    // Source inside the fixed backup directory (removed as a leftover).
    () => {
      fs.mkdirSync(`${target}.old.tmp`);
      fs.copyFileSync(snapshotPath, `${target}.old.tmp/snap.json`);
      return { source: `${target}.old.tmp/snap.json`, output: target, watch: [`${target}.old.tmp/snap.json`] };
    },
    // Source path is exactly the staging location (a file, not inside a dir).
    () => ({ source: `${target}.export.tmp`, output: target, watch: [`${target}.export.tmp`] }),
  ];

  let index = 0;
  for (const layout of layouts) {
    if (index === 3) fs.copyFileSync(snapshotPath, `${target}.export.tmp`);
    const { source, output, watch } = layout();
    const before = new Map(watch.map((file) => [file, fs.readFileSync(file)]));
    assert.throws(
      () => exportMarkdown(source, output),
      (error) => error.code === 'INVALID_OPTIONS',
      `layout ${index}`,
    );
    for (const [file, bytes] of before) {
      assert.ok(fs.existsSync(file), `layout ${index}: ${file} survives`);
      assert.deepEqual(fs.readFileSync(file), bytes, `layout ${index}: ${file} unchanged`);
    }
    assert.ok(!fs.existsSync(target), `layout ${index}: no package directory created`);
    fs.rmSync(cwd, { recursive: true, force: true });
    fs.mkdirSync(cwd);
    index += 1;
  }
});

