    fs.readFileSync(path.join(cwd, 'pkg.export.tmp', 'snap.json')),
    fs.readFileSync(path.join(cwd, 'snap.json')),
  );
  assert.ok(!fs.existsSync(path.join(cwd, 'pkg')), 'no package emitted');
});

